import json,subprocess
p=subprocess.run(['ffprobe','-v','error','-show_streams','-show_format','-of','json','out/contagious-yawn-final.mp4'],capture_output=True,text=True,check=True);d=json.loads(p.stdout); vs=next(x for x in d['streams'] if x['codec_type']=='video'); a=next(x for x in d['streams'] if x['codec_type']=='audio'); assert vs['width']==1080 and vs['height']==1920; assert abs(float(vs['r_frame_rate'].split('/')[0])/float(vs['r_frame_rate'].split('/')[1])-60)<.01; assert float(a['duration'])>80; print('VALIDATED',vs['width'],vs['height'],vs['r_frame_rate'],a['duration'],d['format']['duration'])
